-- RECONSTRUCTION TOTALE DES TRANSACTIONS BONUS
-- 9 jours × tous membres × tous types
-- =====================================================

-- STEP 1 : Supprimer TOUTES les transactions *_daily existantes
DELETE FROM wallet_transactions
WHERE wallet_type = 'principal'
  AND transaction_type IN (
    'prime_leadership_daily',
    'fast_start_daily',
    'bonus_influence_daily',
    'bonus_rayonnement_daily',
    'valorisation_recommandation_daily'
  );

