-- STEP 3 : Recalculer balance = non-bonus credits + bonus corrects
--          = (total actuel) - (transactions *_daily actuelles supprimées) + total_correct

-- 210e5ddb... | actuel=19530.00 | correct=8910.00 | delta=-10620.00
UPDATE wallets SET balance = ROUND(balance + (-10620.0000000000), 4),     updated_at = '2026-06-09 14:00:00' WHERE member_id = '210e5ddb-58fd-4eb6-8361-c60c7b576a3d';

